    hero: { healthMonitor: '+ निःशुल्क हेल्थ मॉनिटर', badge: 'AI-संचालित त्वचा निगरानी', title: 'AI की मदद से अपनी त्वचा पर नज़र रखें', accuracy: 'AI ABCDE विश्लेषण', description: "आपकी त्वचा एक कहानी कहती है। SkinGuard AI उसे पढ़ने में मदद करता है। AI-सहायता प्राप्त छवि विश्लेषण के साथ आप घर पर ही तिल और त्वचा के घावों की तस्वीरें ले सकते हैं, उन्हें तारीख के साथ एक जगह रख सकते हैं, और देख सकते हैं कि वे हफ्तों, महीनों और वर्षों में कैसे बदलते हैं — ताकि आप जान सकें कि अपने त्वचा विशेषज्ञ को क्या दिखाना है।", startMonitoring: 'निगरानी शुरू करें', viewPlans: 'योजनाएं देखें', freeToStart: 'शुरू करने के लिए निःशुल्क', noAccountNeeded: "क्रेडिट कार्ड की आवश्यकता नहीं", privateSecure: 'आपका डेटा कभी नहीं बेचा जाता', aiAccuracy: 'AI ABCDE विश्लेषण', aiAccuracyDesc: 'ABCDE मार्करों पर आधारित' },
    features: { title: 'शक्तिशाली सुविधाएं', subtitle: 'व्यापक त्वचा स्वास्थ्य निगरानी के लिए आवश्यक सब कुछ', smartCapture: 'स्मार्ट कैप्चर', smartCaptureDesc: "अपने फोन के कैमरे से तिल और त्वचा के धब्बों की विस्तृत तस्वीरें लें या गैलरी से अपलोड करें। हर तस्वीर तारीख के साथ सहेजी जाती है और ABCDE मानकों के अनुसार वर्णित की जाती है, ताकि आप उसे ट्रैक कर सकें।", bodyMap: 'इंटरैक्टिव शरीर मानचित्र', bodyMapDesc: 'एक इंटरैक्टिव शरीर आरेख पर तिलों को चिह्नित और व्यवस्थित करें। शरीर क्षेत्र, गंभीरता और निगरानी प्राथमिकता के अनुसार वर्गीकृत करें। आपकी संपूर्ण त्वचा प्रोफ़ाइल एक स्थान पर।', comparison: 'AI तुलना', comparisonDesc: "किसी भी तिल का पूरा इतिहास साथ-साथ फोटो तुलना के साथ देखें, साथ ही समय के साथ उसके ABCDE स्कोर का चार्ट, ताकि आप स्वयं आंक सकें कि वह बदल रहा है या नहीं।", reminders: 'स्मार्ट रिमाइंडर', remindersDesc: "प्रत्येक तिल के लिए जाँच का अंतराल निर्धारित करें। अंतराल बीत जाने पर ऐप उस तिल को आपके डैशबोर्ड पर देय के रूप में चिह्नित करता है, ताकि कुछ भी छूट न जाए।" },
    abcde: { title: 'ABCDE विश्लेषण', subtitle: 'ABCDE नियम पर आधारित, जिसे त्वचा रोग विशेषज्ञ स्व-परीक्षण के लिए सिखाते हैं', asymmetry: 'विषमता', asymmetryDesc: 'एक आधा दूसरे से मेल नहीं खाता', border: 'सीमा', borderDesc: 'किनारे अनियमित, खुरदरे या धुंधले हैं', color: 'रंग', colorDesc: 'भूरे, काले या गुलाबी रंग की छाया के साथ असमान रंग', diameter: 'व्यास', diameterDesc: '6 मिमी से बड़ा (पेंसिल इरेज़र का आकार)', evolution: 'विकास', evolutionDesc: 'समय के साथ आकार, आकृति या रंग में परिवर्तन' },
