    hero: { healthMonitor: '+ Theo dõi sức khỏe miễn phí', badge: 'Giám sát da được cung cấp bởi AI', title: 'Theo dõi làn da của bạn với AI', accuracy: 'Phân tích ABCDE bằng AI', description: "Làn da của bạn kể một câu chuyện. SkinGuard AI giúp bạn đọc nó. Với phân tích hình ảnh có AI hỗ trợ, bạn có thể chụp nốt ruồi và tổn thương da ngay tại nhà, lưu chúng kèm ngày tháng ở một nơi, và thấy chúng thay đổi thế nào qua nhiều tuần, nhiều tháng, nhiều năm — để biết cần cho bác sĩ da liễu xem điều gì.", startMonitoring: 'Bắt đầu giám sát', viewPlans: 'Xem kế hoạch', freeToStart: 'Miễn phí để bắt đầu', noAccountNeeded: "Không cần thẻ tín dụng", privateSecure: 'Chúng tôi không bao giờ bán dữ liệu của bạn', aiAccuracy: 'Phân tích ABCDE bằng AI', aiAccuracyDesc: 'Dựa trên các dấu hiệu ABCDE' },
    features: { title: 'Các tính năng mạnh mẽ', subtitle: 'Mọi thứ bạn cần để giám sát sức khỏe da toàn diện', smartCapture: 'Chụp thông minh', smartCaptureDesc: "Chụp ảnh chi tiết nốt ruồi và các đốm da bằng camera điện thoại hoặc tải lên từ thư viện. Mỗi ảnh được lưu kèm ngày tháng và mô tả theo các tiêu chí ABCDE để bạn có thể theo dõi.", bodyMap: 'Bản đồ cơ thể tương tác', bodyMapDesc: 'Đánh dấu và sắp xếp nốt ruồi trên sơ đồ cơ thể tương tác. Phân loại theo vùng cơ thể, mức độ nghiêm trọng và ưu tiên giám sát. Hồ sơ da hoàn chỉnh của bạn ở một nơi.', comparison: 'So sánh AI', comparisonDesc: "Xem toàn bộ lịch sử của bất kỳ nốt ruồi nào với ảnh so sánh cạnh nhau, cùng biểu đồ điểm ABCDE theo thời gian để bạn tự đánh giá xem nó có đang thay đổi hay không.", reminders: 'Nhắc nhở thông minh', remindersDesc: "Đặt khoảng thời gian kiểm tra cho từng nốt ruồi. Khi hết khoảng thời gian đó, ứng dụng đánh dấu nốt ruồi là đến hạn trên bảng điều khiển của bạn, để không bỏ sót điều gì." },
    abcde: { title: 'Phân tích ABCDE', subtitle: 'Dựa trên quy tắc ABCDE mà bác sĩ da liễu hướng dẫn để tự kiểm tra da', asymmetry: 'Bất đối xứng', asymmetryDesc: 'Một nửa không khớp với nửa kia', border: 'Đường viền', borderDesc: 'Các cạnh không đều, gồ ghề hoặc mờ', color: 'Màu sắc', colorDesc: 'Màu không đều với các sắc thái nâu, đen hoặc hồng', diameter: 'Đường kính', diameterDesc: 'Lớn hơn 6 mm (kích thước tẩy chì)', evolution: 'Sự tiến hóa', evolutionDesc: 'Thay đổi kích thước, hình dạng hoặc màu sắc theo thời gian' },
